/// <summary>
/// Abstract class for calculating MDF based on different delivery charge types
/// </summary>
public abstract class METCustomerMDFCalculationRecord
{
    MetCustomerMdfSetupTable customerMDFSetupTable;

}

Method.Source:
/// <summary>
/// Construct method to create appropriate subclass based on DeliveryChargeType
/// </summary>
/// <param name = "_customerMDFSetupTable">METCustomerMdfSetupTable</param>
/// <returns>METCustomerMDFCalculationRecord</returns>
public static METCustomerMDFCalculationRecord construct(METCustomerMdfSetupTable _customerMDFSetupTable)
{
    // Typical implementation of a construct method
    switch (_customerMDFSetupTable.DeliveryChargeType)
    {
        case METDeliveryChargeType::CartonTotalCaseFee:
            return new METCustomerMDFCalculationRecord_CartonCaseFee(_customerMDFSetupTable);
        case METDeliveryChargeType::CartonTotalFlatFee:
            return new METCustomerMDFCalculationRecord_CartonFlatFee(_customerMDFSetupTable);
        case METDeliveryChargeType::TotalDeliveryFees:
            return new METCustomerMDFCalculationRecord_DeliveryFee(_customerMDFSetupTable);
        case METDeliveryChargeType::TotalInvoiceAmount:
            return new METCustomerMDFCalculationRecord_InvoiceAmount(_customerMDFSetupTable);
        default:
            throw error("@MET:UnsupportedDeliveryChargeType" + enum2str(_customerMDFSetupTable.DeliveryChargeType));
    }
}

/// <summary>
/// New method to initialize the class with the provided METCustomerMdfSetupTable
/// </summary>
/// <param name = "_customerMDFSetupTable">METCustomerMdfSetupTable</param>
void new(METCustomerMdfSetupTable _customerMDFSetupTable)
{
    customerMDFSetupTable = _customerMDFSetupTable;
}

/// <summary>
/// Calculate quantity based on WMSOrderTrans
/// </summary>
/// <param name = "_wMSOrderTrans">WMSOrderTrans</param>
/// <returns>Qty</returns>
Qty calcQty(WMSOrderTrans _wMSOrderTrans)
{
    SalesLine salesLine = SalesLine::findInventTransId(_wMSOrderTrans.inventTransId);
    return EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(
        salesLine.ItemId,
        salesLine.InventDimId,
        _wMSOrderTrans.qty,
        InventTableModule::find(salesLine.ItemId, ModuleInventPurchSales::Invent).UnitId,
        salesLine.SalesUnit);
}

